PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS usuarios(id TEXT PRIMARY KEY,nome TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,senha_hash TEXT,papel TEXT NOT NULL DEFAULT 'pendente' CHECK(papel IN('socio','equipe','pendente')),status TEXT NOT NULL DEFAULT 'ativo' CHECK(status IN('ativo','bloqueado','pendente')),criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS solicitacoes_acesso(id TEXT PRIMARY KEY,nome TEXT NOT NULL,email TEXT NOT NULL COLLATE NOCASE,status TEXT NOT NULL DEFAULT 'pendente' CHECK(status IN('pendente','aprovada','recusada')),analisado_por TEXT REFERENCES usuarios(id),criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,analisado_em TEXT);
CREATE TABLE IF NOT EXISTS permissoes(id TEXT PRIMARY KEY,usuario_id TEXT NOT NULL REFERENCES usuarios(id),recurso TEXT NOT NULL,pode_visualizar INTEGER NOT NULL DEFAULT 0,pode_criar INTEGER NOT NULL DEFAULT 0,pode_editar INTEGER NOT NULL DEFAULT 0,pode_excluir INTEGER NOT NULL DEFAULT 0,UNIQUE(usuario_id,recurso));
CREATE TABLE IF NOT EXISTS clientes(id TEXT PRIMARY KEY,nome TEXT NOT NULL,telefone TEXT,email TEXT,observacoes TEXT,criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS veiculos(id TEXT PRIMARY KEY,cliente_id TEXT NOT NULL REFERENCES clientes(id),marca TEXT,modelo TEXT,ano INTEGER,placa TEXT,cor TEXT,observacoes TEXT,foto_data TEXT);
CREATE TABLE IF NOT EXISTS catalogo_servicos(id TEXT PRIMARY KEY,nome TEXT NOT NULL,descricao TEXT,ativo INTEGER NOT NULL DEFAULT 1,preco_sugerido_centavos INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS atendimentos(id TEXT PRIMARY KEY,cliente_id TEXT NOT NULL REFERENCES clientes(id),veiculo_id TEXT REFERENCES veiculos(id),data_hora TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'agendado' CHECK(status IN('agendado','em_andamento','concluido','cancelado')),valor_centavos INTEGER NOT NULL DEFAULT 0,desconto_centavos INTEGER NOT NULL DEFAULT 0,acrescimo_centavos INTEGER NOT NULL DEFAULT 0,responsavel_id TEXT REFERENCES usuarios(id),criado_por TEXT REFERENCES usuarios(id),observacoes TEXT,criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS atendimento_servicos(atendimento_id TEXT NOT NULL REFERENCES atendimentos(id),servico_id TEXT REFERENCES catalogo_servicos(id),descricao TEXT NOT NULL,valor_centavos INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(atendimento_id,descricao));
CREATE TABLE IF NOT EXISTS pagamentos(id TEXT PRIMARY KEY,atendimento_id TEXT NOT NULL REFERENCES atendimentos(id),valor_centavos INTEGER NOT NULL CHECK(valor_centavos>0),metodo TEXT NOT NULL CHECK(metodo IN('dinheiro','pix','cartao','outro')),modalidade TEXT NOT NULL DEFAULT 'nao_aplicavel',status TEXT NOT NULL DEFAULT 'pendente' CHECK(status IN('pendente','recebido','estornado')),recebido_em TEXT,criado_por TEXT REFERENCES usuarios(id),movimento_id TEXT UNIQUE,criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS despesas(id TEXT PRIMARY KEY,descricao TEXT NOT NULL,valor_centavos INTEGER NOT NULL CHECK(valor_centavos>0),vencimento TEXT,categoria TEXT NOT NULL DEFAULT 'outros',status TEXT NOT NULL DEFAULT 'pendente' CHECK(status IN('pendente','paga','cancelada')),metodo TEXT,pago_em TEXT,criado_por TEXT REFERENCES usuarios(id),criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS taxas_pagamento(metodo TEXT PRIMARY KEY CHECK(metodo IN('credito','debito')),taxa_percentual REAL NOT NULL DEFAULT 0 CHECK(taxa_percentual>=0 AND taxa_percentual<=100),atualizado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO taxas_pagamento(metodo,taxa_percentual) VALUES('credito',0),('debito',0);
CREATE TABLE IF NOT EXISTS movimentacoes(id TEXT PRIMARY KEY,tipo TEXT NOT NULL CHECK(tipo IN('entrada','saida','ajuste')),origem TEXT NOT NULL,origem_id TEXT,descricao TEXT NOT NULL,valor_centavos INTEGER NOT NULL CHECK(valor_centavos>0),metodo TEXT,ocorrido_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,criado_por TEXT REFERENCES usuarios(id),UNIQUE(origem,origem_id));
CREATE TABLE IF NOT EXISTS caixas(id TEXT PRIMARY KEY,data_abertura TEXT NOT NULL,saldo_inicial_centavos INTEGER NOT NULL DEFAULT 0,aberto_por TEXT REFERENCES usuarios(id),status TEXT NOT NULL DEFAULT 'aberto' CHECK(status IN('aberto','fechado')));
CREATE TABLE IF NOT EXISTS fechamentos(id TEXT PRIMARY KEY,caixa_id TEXT NOT NULL UNIQUE REFERENCES caixas(id),data_fechamento TEXT NOT NULL,total_esperado_centavos INTEGER NOT NULL,total_contado_centavos INTEGER NOT NULL,diferenca_centavos INTEGER NOT NULL,justificativa TEXT,fechado_por TEXT REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS fornecedores(id TEXT PRIMARY KEY,nome TEXT NOT NULL,telefone TEXT,email TEXT,observacoes TEXT);
CREATE TABLE IF NOT EXISTS produtos(id TEXT PRIMARY KEY,nome TEXT NOT NULL,unidade TEXT NOT NULL DEFAULT 'un',quantidade REAL NOT NULL DEFAULT 0 CHECK(quantidade>=0),estoque_minimo REAL NOT NULL DEFAULT 0 CHECK(estoque_minimo>=0),custo_unitario_centavos INTEGER NOT NULL DEFAULT 0 CHECK(custo_unitario_centavos>=0),fornecedor_id TEXT REFERENCES fornecedores(id),ativo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS movimentacoes_estoque(id TEXT PRIMARY KEY,produto_id TEXT NOT NULL REFERENCES produtos(id),tipo TEXT NOT NULL CHECK(tipo IN('compra','consumo','perda','ajuste')),quantidade REAL NOT NULL CHECK(quantidade>0),custo_unitario_centavos INTEGER,atendimento_id TEXT REFERENCES atendimentos(id),motivo TEXT NOT NULL,criado_por TEXT REFERENCES usuarios(id),criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS arquivos(id TEXT PRIMARY KEY,chave_r2 TEXT NOT NULL UNIQUE,cliente_id TEXT REFERENCES clientes(id),veiculo_id TEXT REFERENCES veiculos(id),atendimento_id TEXT REFERENCES atendimentos(id),tipo TEXT NOT NULL,enviado_por TEXT REFERENCES usuarios(id),criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS consentimentos(id TEXT PRIMARY KEY,cliente_id TEXT NOT NULL REFERENCES clientes(id),arquivo_id TEXT REFERENCES arquivos(id),finalidade TEXT NOT NULL CHECK(finalidade IN('armazenamento','divulgacao_publica')),concedido INTEGER NOT NULL CHECK(concedido IN(0,1)),registrado_por TEXT REFERENCES usuarios(id),registrado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auditoria(id TEXT PRIMARY KEY,usuario_id TEXT REFERENCES usuarios(id),acao TEXT NOT NULL,entidade TEXT NOT NULL,entidade_id TEXT,detalhes TEXT,criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS backups(id TEXT PRIMARY KEY,chave_r2 TEXT NOT NULL,checksum TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('concluido','falhou')),criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_atendimentos_data ON atendimentos(data_hora);
CREATE INDEX IF NOT EXISTS idx_atendimentos_cliente ON atendimentos(cliente_id);
CREATE INDEX IF NOT EXISTS idx_movimentacoes_data ON movimentacoes(ocorrido_em);
CREATE INDEX IF NOT EXISTS idx_estoque_produto ON movimentacoes_estoque(produto_id);